import sys; sys.path.insert(0,'/home/claude/ac-mdcu/parts')
from l22_common import mk, save
Q={}

mk(Q, 121, ['s7'],
 stem='A 62-year-old woman received chest wall radiotherapy after mastectomy 3 years ago. The irradiated skin is thin, shiny, hyperpigmented and firm, and a minor scratch there has become an ulcer that has not healed for 2 months. What best explains the poor healing?',
 opts=['Vitamin C deficiency impairing collagen cross-linking','Obliterative endarteritis with tissue fibrosis','Acute basal cell death with moist desquamation','Venous hypertension with pericapillary fibrin cuffs','Sustained pressure above capillary closing pressure'],
 interp='หญิงเคยฉายรังสีผนังทรวงอกเมื่อ 3 ปีก่อน ผิวบาง ตึงแข็ง สีเข้ม และรอยข่วนเล็กน้อยกลายเป็นแผลที่ไม่หายนาน 2 เดือน = late radiation injury ของผิวหนัง (chronic radiation dermatitis) → ถามกลไกที่ทำให้แผลไม่หาย ต้องใช้หลักผลของรังสีระยะยาวเกิน 6 เดือนต่อหลอดเลือดและเนื้อเยื่อเกี่ยวพัน ไม่ใช่ผลระยะเฉียบพลัน',
 why='รังสี<b>ยับยั้งการแบ่งตัวของเซลล์</b> โดยเฉพาะเซลล์ที่แบ่งเร็ว ผลต่อผิวจึงแบ่งเป็น 2 ระยะ · <b>ระยะเฉียบพลัน</b> (ระหว่างฉายถึงไม่กี่สัปดาห์): basal cell ตาย → ผิวแดง ลอกแห้งหรือลอกเปียก (moist desquamation) แล้วหายได้ ทิ้ง hyperpigmentation · <b>ระยะยาวเกิน 6 เดือน</b>: endothelium เสียหายถาวร เกิด <b>obliterative endarteritis</b> หลอดเลือดเล็กอุดตัน (thrombosis) และผนังหลอดเลือดตาย ร่วมกับ fibroblast ผิดปกติที่ถูกกระตุ้นด้วย TGF-β ต่อเนื่อง → เนื้อเยื่อกลายเป็น <b>hypovascular · hypocellular · hypoxic</b> และเป็นพังผืดมากขึ้นเรื่อย ๆ (progressive fibrosis) ผิวจึงบาง แข็ง มี telangiectasia · บาดแผลเล็กน้อยในเนื้อเยื่อนี้ขาดทั้งเลือด ออกซิเจน และเซลล์ที่จะซ่อม จึง<b>ไม่หาย</b> · การรักษาที่ได้ผลคือ<b>ตัดเนื้อเยื่อที่ถูกรังสีออกจนถึงเนื้อที่เลือดออกดี แล้วปิดด้วย flap ที่มีเลือดเลี้ยงจากนอกบริเวณที่ฉาย</b> เช่น latissimus dorsi หรือ omentum ส่วน skin graft มักไม่ติดบนพื้นที่ถูกฉาย · แผลเรื้อรังบนผิวที่เคยฉายต้อง biopsy ก่อนเพื่อแยกมะเร็งที่เกิดจากรังสี · ชีทหน้า 7 <b>"ในระยะยาวมากกว่า 6 เดือน เส้นเลือดจะเกิดการอุดตัน (thrombosis) และผนังหลอดเลือดตายด้วย ทำให้เนื้อเยื่อบริเวณดังกล่าวขาดเลือด เกิดเป็นพังผืด (progressive fibrosis) และเกิดแผลที่ไม่หายตามมาได้"</b>',
 wrong={
  'A':'การขาดวิตามินซีทำให้ prolyl และ lysyl hydroxylase ทำงานไม่ได้ collagen จึงไม่ cross-link แผลหายช้าและแผลเป็นเก่าแยกออก — แต่ผิวในโจทย์ผิดปกติเฉพาะบริเวณที่ฉายรังสี ไม่ใช่ทั้งตัว จึงอธิบายด้วยการขาดสารอาหารไม่ได้ · จะถูกถ้าชายสูงอายุติดสุรากินแต่ข้าวขาว มีเลือดออกตามไรฟัน จุดเลือดออกรอบรูขุมขน และแผลที่ขาไม่หายหลายเดือน',
  'C':'Basal cell ตายแบบเฉียบพลันพร้อมผิวลอกเปียกเป็นผลของรังสีช่วงระหว่างฉายถึงไม่กี่สัปดาห์หลังฉาย และมักหายได้เมื่อหยุดรังสี — แผลที่เกิด 3 ปีหลังฉายบนผิวที่แข็งเป็นพังผืดเป็นผลระยะยาว · จะถูกถ้าหญิงกำลังฉายรังสีเต้านมสัปดาห์ที่ 5 มีผิวใต้ราวนมแดงลอกเปียกเป็นแผลตื้นที่ยังไม่หายระหว่างฉาย',
  'D':'Venous hypertension ทำให้เม็ดเลือดขาวและ fibrin รั่วออกรอบ capillary ขัดขวางการแลกเปลี่ยนออกซิเจน เป็นกลไกของ venous ulcer ที่ขา — ผนังทรวงอกไม่ใช่ตำแหน่งที่มีความดันหลอดเลือดดำสูง · จะถูกถ้าหญิงมีเส้นเลือดขอดและผิวคล้ำแข็งที่ข้อเท้าด้านใน (lipodermatosclerosis) มีแผลตื้นที่ malleolus ด้านในไม่หายหลายเดือน และ ABI ปกติ',
  'E':'แรงกดที่สูงกว่าความดันปิด capillary (ราว 32 mmHg) นานพอทำให้เนื้อเยื่อขาดเลือดและตาย เป็นกลไกของแผลกดทับเหนือปุ่มกระดูก — ผนังทรวงอกด้านหน้าไม่ใช่จุดรับน้ำหนัก และผิวผิดปกติตามขอบเขตที่ฉายรังสี · จะถูกถ้าชายอัมพาตครึ่งล่างนั่งรถเข็นทั้งวันมีแผลลึกเหนือ ischial tuberosity ที่ไม่หายเพราะยังนั่งทับต่อเนื่อง'},
 trap='คำว่า basal cell และผื่นแดงจากรังสีเป็นสิ่งที่จำได้ก่อน จึงชวนเลือกผลระยะเฉียบพลัน แต่เวลา 3 ปีหลังฉายและผิวที่บางแข็งเป็นผลระยะยาว · หลักแยก: ภายในไม่กี่สัปดาห์ = เซลล์ที่แบ่งเร็วตาย หายได้ · เกิน 6 เดือน = หลอดเลือดอุดตันและพังผืด ไม่หายเอง',
 summary=[
  'แกน: แผลไม่หายบนผิวที่ฉายรังสีนานเกิน 6 เดือน = หลอดเลือดอุดตัน (obliterative endarteritis, thrombosis) + ผนังหลอดเลือดตาย → ขาดเลือด → progressive fibrosis',
  'ระยะเฉียบพลัน: ผิวแดง basal cell ตาย ลอกแห้งหรือลอกเปียก หายแล้วทิ้ง hyperpigmentation (ชีทหน้า 7)',
  'เนื้อเยื่อหลังฉายรังสี: hypovascular · hypocellular · hypoxic → ผิวบาง แข็ง telangiectasia แผลเล็กก็ไม่หาย',
  'รักษา: ตัดเนื้อที่ถูกรังสีทำลายจนถึงเนื้อดี + ปิดด้วย flap ที่เลือดเลี้ยงจากนอกบริเวณฉาย · skin graft มักไม่ติด',
  'แผลเรื้อรังบนผิวที่ฉายรังสี → biopsy แยก SCC, BCC และ angiosarcoma ที่เกิดจากรังสี',
  'ทางเลือกเสริม: hyperbaric oxygen (หลักฐานยังไม่แน่นอน) · pentoxifylline ร่วม vitamin E เพื่อลดพังผืดจากรังสี'],
 opinion='เห็นด้วยกับคำตอบ B ความมั่นใจสูง — ชีทหน้า 7 แยกผลระยะเฉียบพลันกับระยะยาวเกิน 6 เดือนไว้ชัด และกลไกหลอดเลือดอุดตันร่วมพังผืดตรงกับตำราปัจจุบัน · ตำราเพิ่มบทบาทของ TGF-β และ fibroblast ที่เสียหาย ซึ่งทำให้พังผืดยังดำเนินต่อแม้หยุดฉายไปหลายปี และย้ำว่าแผลเรื้อรังบนผิวที่ฉายต้อง biopsy ก่อนวางแผนปิดแผล · ชีทไม่ได้กล่าวถึงการรักษา แนวปัจจุบันใช้การตัดเนื้อเยื่อที่เสียออกแล้วปิดด้วย flap ที่มีเลือดดีเป็นหลัก ส่วน hyperbaric oxygen ยังเป็นเพียงทางเลือกเสริม',
 mnemonic='<b>"รังสี 2 ระยะ: สัปดาห์ = แดง ลอก หาย · เกิน 6 เดือน = ตัน ตาย พังผืด ไม่หาย → ตัดออกแล้วเอา flap มาปิด"</b>',
 guide="Sabiston Textbook of Surgery 21st ed. (2022) — Wound healing; Grabb and Smith's Plastic Surgery 8th ed. (2020) — Chest wall reconstruction and radiation injury",
 variants=[
  'หญิงฉายรังสีเต้านมเมื่อ 7 ปีก่อน มีผื่นม่วงคล้ำหลายจุดและก้อนนูนเลือดออกง่ายบนผิวที่ฉาย → สงสัย radiation-associated angiosarcoma ต้อง biopsy',
  'ผิวบริเวณที่ฉายรังสีครบ 4 สัปดาห์แดงและลอกแห้ง → ทาครีมให้ความชุ่มชื้น เลี่ยงการเสียดสี ส่วนใหญ่หายได้เองหลังจบการฉาย',
  'ชายทำ cardiac intervention ซ้ำหลายครั้งใช้ fluoroscopy นาน ต่อมามีแผลเรื้อรังที่หลังบนตรงตำแหน่งลำรังสี → radiation-induced skin injury จากการตรวจด้วยรังสี ไม่ใช่เฉพาะรังสีรักษา'])

mk(Q, 122, ['s8','s9'],
 stem='A 27-year-old obese woman who smokes has had recurrent painful nodules in both axillae and the groin for 5 years. They drain foul-smelling pus through interconnected sinus tracts and heal with rope-like scars. What is the diagnosis?',
 opts=['Hidradenitis suppurativa','Cutaneous actinomycosis','Recurrent staphylococcal furunculosis','Multiple inflamed epidermoid cysts','Carbuncle'],
 interp='หญิงอ้วน สูบบุหรี่ มีก้อนเจ็บเป็นซ้ำที่รักแร้สองข้างและขาหนีบนาน 5 ปี มีหนองกลิ่นเหม็นออกทาง sinus tract ที่เชื่อมกัน และหายเป็นแผลเป็นแบบเชือก → ถามการวินิจฉัย ต้องใช้หลักสามข้อของ hidradenitis suppurativa คือรอยโรคลักษณะเฉพาะ ตำแหน่งเฉพาะ และเป็นเรื้อรังซ้ำ ๆ',
 why='<b>Hidradenitis suppurativa (HS)</b> เป็นโรคอักเสบเรื้อรังของ<b>ส่วนปลายรูขุมขน</b>ในบริเวณที่มีต่อม apocrine: ชั้น infundibulum หนาตัวอุดตัน → ขุมขนแตก เนื้อหาไหลเข้า dermis กระตุ้นการอักเสบ ต่อม apocrine ถูกลามเป็นผลตามมา แล้วติดเชื้อซ้ำเป็นฝี · วินิจฉัยทางคลินิกล้วน ไม่มี lab ยืนยัน ใช้ 3 เกณฑ์: <b>(1) รอยโรคจำเพาะ</b> — ก้อนลึกเจ็บ ฝี sinus tract แผลเป็นแบบเชือกหรือสะพาน และ double-ended comedone · <b>(2) ตำแหน่งจำเพาะ</b> — รักแร้ ขาหนีบ รอบทวาร ใต้ราวนม ก้น · <b>(3) เป็นเรื้อรังซ้ำ</b> อย่างน้อย 2 ครั้งใน 6 เดือน · ปัจจัยเสี่ยงหลักคือ<b>สูบบุหรี่และอ้วน</b> พบในหญิงมากกว่า เริ่มหลังวัยรุ่น · จัดระยะด้วย <b>Hurley</b>: I ฝีไม่มี tract · II ฝีซ้ำมี tract และแผลเป็นแยกเป็นจุด · III tract เชื่อมกันทั่วทั้งบริเวณ ซึ่งระยะนี้กำหนดการรักษา · ชีทหน้า 8 <b>"Hidradenitis suppurativa เกิดจากความผิดปกติของ epithelium ของขนส่วนปลาย ทำให้เกิดการอุดตันของ apocrine gland … มักเกิดที่ รักแร้ ขาหนีบและรอบรูทวาร"</b>',
 wrong={
  'B':'Actinomycosis เป็นการติดเชื้อ Actinomyces แบบ granulomatous suppurative ทำให้ก้อนแข็งในผิวชั้นลึกมีรูหนองหลายรู คล้าย HS แต่มักเป็นก้อนเดียวที่ลามข้ามชั้นเนื้อเยื่อ พบที่ศีรษะใบหน้ามากที่สุด และไม่เลือกตำแหน่งที่มีต่อม apocrine สองข้าง · จะถูกถ้าชายหลังถอนฟันกรามล่างมีก้อนแข็งเหมือนไม้ที่มุมขากรรไกร มีรูหนองหลายรูที่พบ sulfur granules',
  'C':'Furunculosis ซ้ำจาก S. aureus เป็นฝีรอบรูขุมขนแต่ละเม็ดที่หายสนิทเมื่อระบายหนอง ไม่สร้าง sinus tract เชื่อมกันหรือแผลเป็นแบบเชือก และเกิดได้ทุกที่ที่มีขน ไม่จำกัดเฉพาะรักแร้ขาหนีบ · จะถูกถ้าชายนักกีฬามวยปล้ำมีฝีเม็ดเดี่ยวที่ต้นขาและก้นซ้ำหลายครั้งในปีเดียว แต่ละเม็ดหายสนิท และพบว่าเป็นพาหะ S. aureus ที่จมูก',
  'D':'Epidermoid cyst อักเสบเป็นก้อนกลมใต้ผิวมี punctum ตรงกลาง แตกแล้วมีเนื้อขาวกลิ่นเหม็นคล้ายเนยเน่า แต่เป็นก้อนเดี่ยวแยกจากกัน ไม่มี tract เชื่อมกันเป็นเครือข่ายในตำแหน่งสองข้างเหมือน HS · จะถูกถ้าชายมีก้อนกลมขนาด 2 cm ที่หลังมานานหลายปีมีรูเปิดเล็กตรงกลาง แล้วเพิ่งบวมแดงเจ็บหลังถูกบีบ',
  'E':'Carbuncle คือ furuncle หลายเม็ดรวมกันเป็นก้อนอักเสบลึกที่มีรูหนองหลายรูเหมือนฝีฝักบัว เป็นการติดเชื้อเฉียบพลันครั้งเดียว ไม่ใช่โรคที่เป็น ๆ หาย ๆ นานหลายปีในหลายตำแหน่ง · จะถูกถ้าชายเบาหวานมีก้อนแข็งแดงเจ็บขนาด 5 cm ที่กลางหลังส่วนบนมาหนึ่งสัปดาห์ มีหนองออกหลายรูและมีไข้'},
 trap='รูหนองหลายรูชวนให้นึกถึง carbuncle หรือ actinomycosis ที่ชีทบรรยายว่ามี sinus tract เหมือนกัน · หลักแยก: HS เลือกตำแหน่งที่มีต่อม apocrine ทั้งสองข้าง เป็นซ้ำนานหลายปี และทิ้งแผลเป็นแบบเชือกกับ double-ended comedone ส่วน carbuncle เป็นก้อนเดียวเฉียบพลัน',
 summary=[
  'แกน: ก้อนเจ็บซ้ำ + sinus tract + แผลเป็น ที่รักแร้ ขาหนีบ รอบทวาร = hidradenitis suppurativa (ชีทหน้า 8)',
  'กลไก: ส่วนปลายรูขุมขนอุดตันและแตก → อักเสบ → ต่อม apocrine ถูกลาม ติดเชื้อซ้ำเป็นฝี',
  'วินิจฉัยทางคลินิก 3 เกณฑ์: รอยโรคจำเพาะ · ตำแหน่งจำเพาะ · เป็นซ้ำอย่างน้อย 2 ครั้งใน 6 เดือน',
  'ปัจจัยเสี่ยง: สูบบุหรี่ อ้วน เพศหญิง หลังวัยรุ่น · โรคร่วม: metabolic syndrome, inflammatory bowel disease, spondyloarthritis',
  'Hurley I ฝีไม่มี tract · II มี tract และแผลเป็นเป็นจุด ๆ · III tract เชื่อมกันทั่วบริเวณ',
  'ชีทให้ประคบอุ่น ยาปฏิชีวนะ ระบายหนอง ดูแลความสะอาด และงดยาดับกลิ่นหลังหาย'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตำแหน่ง ลักษณะรอยโรค และความเรื้อรังครบทั้ง 3 เกณฑ์ ร่วมกับปัจจัยเสี่ยงอ้วนและสูบบุหรี่ และรูปในชีทหน้า 9 ก็แสดงผิวขรุขระมีแผลเป็นและรูหนองหลายจุดแบบเดียวกัน · จุดที่ต่างจากความรู้ปัจจุบัน: ชีทหน้า 8 อธิบายว่าโรคเกิดจาก apocrine gland อุดตันแล้วติดเชื้อ แต่ North American HS guideline 2019 และ European S1 guideline 2015 ถือว่าจุดเริ่มคือการอุดตันของส่วนปลายรูขุมขน (follicular occlusion) เป็นโรคอักเสบเรื้อรังทางภูมิคุ้มกัน การติดเชื้อเป็นปัจจัยซ้ำเติม · คำแนะนำงดยาดับกลิ่นยังไม่มีหลักฐานชัด',
 mnemonic='<b>"HS = 3 ซ้ำ: ที่ซ้ำ (รักแร้ ขาหนีบ ทวาร) · ก้อนซ้ำ · แผลเป็นซ้อนเป็นเชือก"</b>',
 guide='Alikhan A, et al. North American clinical management guidelines for hidradenitis suppurativa, Part I. J Am Acad Dermatol 2019; Zouboulis CC, et al. European S1 guideline for the treatment of hidradenitis suppurativa. J Eur Acad Dermatol Venereol 2015',
 variants=[
  'ชายวัยรุ่นขนดกมีรูเล็กหลายรูที่แนวกลางร่องก้น มีหนองซ้ำและมีเส้นขนโผล่จากรู → pilonidal disease ไม่ใช่ HS',
  'หญิงมีก้อนเจ็บซ้ำใต้ราวนมสองข้าง ตรวจพบสิวหัวดำที่มีสองรูเชื่อมกัน → HS ตำแหน่ง inframammary',
  'ชายเป็น HS ที่ก้นมากว่า 20 ปี มีแผลขอบนูนแข็งโตเร็ว → biopsy หา squamous cell carcinoma',
  'ผู้ป่วย HS มีท้องเสียเรื้อรังและมี fistula รอบทวาร → ตรวจหา Crohn disease ที่พบร่วมกับ HS ได้'])

mk(Q, 123, ['s8'],
 stem='A 34-year-old man has had axillary hidradenitis suppurativa for 10 years. Despite repeated drainage and long antibiotic courses, the entire axilla is now scarred, with multiple interconnected draining sinus tracts. What is the most appropriate treatment now?',
 opts=['Warm compresses with continued observation','Intralesional corticosteroid injection alone','Oral clindamycin and rifampicin for 10 weeks','Wide excision of all diseased skin and tracts','Repeat incision and drainage of the largest abscess'],
 interp='HS ที่รักแร้นาน 10 ปี ระบายหนองและให้ยาซ้ำแล้วไม่หาย ทั้งรักแร้เป็นแผลเป็นและมี sinus tract เชื่อมกันหลายแนว = Hurley stage III → ถามการรักษาที่เหมาะที่สุดตอนนี้ ต้องใช้หลักว่า tract ที่บุด้วย epithelium ไม่หายด้วยยาหรือการระบาย ต้องตัดออกทั้งหมด',
 why='Sinus tract ใน HS <b>บุด้วย epithelium</b> และเชื่อมกันใต้ผิวเป็นเครือข่าย ยาปฏิชีวนะลดการอักเสบได้ชั่วคราว ส่วนการกรีดระบายเพียงเปิดฝีหนึ่งจุดโดยไม่ได้เอา tract ออก โรคจึง<b>กลับเป็นซ้ำแทบทุกราย</b>หลัง I&D · เมื่อเป็น <b>Hurley III</b> (tract เชื่อมกันและแผลเป็นทั่วทั้งบริเวณ) การรักษาที่หวังผลหายคือ<b>ตัดผิวและเนื้อเยื่อใต้ผิวที่เป็นโรคออกทั้งหมด</b>จนถึงไขมันปกติ (wide excision) ซึ่งอัตรากลับเป็นซ้ำเฉพาะที่ต่ำที่สุดเมื่อเทียบกับการผ่าแบบจำกัด · แผลที่เหลือปิดได้ 3 แบบ: ปล่อยหายเอง (secondary intention) · <b>skin graft</b> · หรือ local flap โดยเฉพาะที่รักแร้เพื่อลดข้อติด ร่วมกับกายภาพยืดแขนหลังผ่าตัด · สำหรับ Hurley II ที่เป็นเฉพาะจุดใช้ deroofing เปิดหลังคา tract ได้ · แนวปัจจุบันมักให้ยาชีววัตถุ (adalimumab) ต่อเนื่องก่อนและหลังผ่าตัดเพื่อคุมโรคบริเวณอื่น ร่วมกับเลิกบุหรี่และลดน้ำหนัก · ชีทหน้า 8 <b>"แต่ถ้าเป็นซ้ำจนเป็นแผลเรื้อรังจำเป็นต้องตัดผิวหนังบริเวณดังกล่าวออกทั้งหมดและปิดแผล ซึ่งอาจต้องใช้การปลูกถ่ายผิวหนัง (skin graft)"</b>',
 wrong={
  'A':'การประคบอุ่นช่วยให้หนองนิ่มและไหลออกง่าย เป็นการดูแลตุ่มอักเสบระยะแรกที่ยังไม่เป็นฝีชัด — ใน Hurley III ที่มี tract เชื่อมกันทั่วรักแร้ การรอดูไม่ทำให้ tract หาย และโรคจะลามมากขึ้น · จะถูกถ้าชายมีตุ่มแดงเจ็บรอบรูขุมขนเม็ดเดียวที่ต้นแขนมาสองวัน ยังไม่ fluctuant และไม่มีไข้ ซึ่งเริ่มด้วยการประคบอุ่นก่อน',
  'B':'การฉีด triamcinolone เข้ารอยโรคช่วยลดปวดและยุบก้อนอักเสบเฉียบพลันได้ภายในไม่กี่วัน ใช้เป็นการรักษาระยะสั้นของก้อนเดี่ยว — แต่ไม่สามารถเอา tract ที่บุด้วย epithelium หลายแนวออกได้ · จะถูกถ้าหญิงเป็น HS Hurley I มีก้อนอักเสบเจ็บเพียงก้อนเดียวที่ขาหนีบเพิ่งเกิด ยังไม่มี tract และต้องการลดปวดอย่างรวดเร็ว',
  'C':'Clindamycin ร่วม rifampicin นานราว 10–12 สัปดาห์เป็นยาทางกินที่ใช้ใน HS ระยะปานกลาง ลดจำนวนก้อนและหนองได้ แต่หยุดยาแล้วมักกลับเป็นซ้ำ และไม่ทำลาย tract ที่เป็นแผลเป็นแล้ว · จะถูกถ้าหญิงเป็น HS Hurley II ที่ขาหนีบมีฝีซ้ำและ tract สั้นแยกเป็นจุด ๆ ซึ่งยังไม่ตอบสนองต่อ tetracycline กิน',
  'E':'การกรีดระบายฝีลดปวดได้ทันที แต่เปิดเพียงช่องเดียวของเครือข่าย tract ที่บุด้วย epithelium โรคจึงกลับมาเกือบทุกราย ไม่ใช่การรักษาที่หวังผลหายใน HS เรื้อรัง · จะถูกถ้าชายไม่เคยเป็น HS มีฝีเดี่ยวขนาด 3 cm ที่ต้นแขนจากรูขุมขนอักเสบ คลำได้ fluctuant และเป็นครั้งแรก'},
 trap='การเห็นฝีที่ใหญ่ที่สุดชวนให้ระบายอีกครั้ง หรือเลือกยาที่ฟังดูเป็นแนวทางมาตรฐานของ HS · หลักแยก: ดูระยะ Hurley ก่อน ระยะ I–II ใช้ยาและหัตถการเล็ก ส่วนระยะ III ที่ tract เชื่อมกันทั่วบริเวณและไม่หายจากยา ต้องตัดออกทั้งหมด',
 summary=[
  'แกน: HS เรื้อรังที่ tract เชื่อมกันและเป็นแผลเป็นทั่วบริเวณ (Hurley III) → wide excision ผิวที่เป็นโรคทั้งหมด + ปิดแผล อาจใช้ skin graft (ชีทหน้า 8)',
  'I&D ลดปวดได้ชั่วคราว แต่โรคกลับซ้ำเกือบทุกราย เพราะไม่เอา tract ที่บุด้วย epithelium ออก',
  'Hurley I: clindamycin ทา ฉีด steroid เข้ารอยโรค · Hurley II: tetracycline กิน, clindamycin + rifampicin, deroofing · Hurley III: wide excision',
  'ปิดแผลหลังตัด: secondary intention · skin graft · local flap (ที่รักแร้ช่วยลดข้อติด)',
  'ยาชีววัตถุ: adalimumab (ตัวแรกที่รับรอง) secukinumab bimekizumab ใช้ในระยะปานกลางถึงรุนแรง และใช้ร่วมกับการผ่าตัด',
  'ทุกระยะ: เลิกบุหรี่ ลดน้ำหนัก ดูแลแผล ควบคุมปวด'],
 opinion='เห็นด้วยกับคำตอบ D ความมั่นใจสูง — ชีทหน้า 8 ให้ตัดผิวบริเวณที่เป็นซ้ำจนเรื้อรังออกทั้งหมด ตรงกับ North American HS guideline 2019 ที่ให้ wide excision ในโรคระยะรุนแรงเพราะอัตรากลับเป็นซ้ำต่ำที่สุด · สิ่งที่ชีทไม่ได้กล่าวถึง: deroofing สำหรับ tract เฉพาะจุดใน Hurley II และยาชีววัตถุ ซึ่งปัจจุบันใช้ร่วมกับการผ่าตัดเพื่อคุมโรคบริเวณอื่น ส่วนคำแนะนำงดยาดับกลิ่นของชีทยังไม่มีหลักฐานรองรับชัดเจน',
 mnemonic='<b>"Tract มีเยื่อบุ = ไม่หายด้วยยา ไม่หายด้วยกรีด → Hurley III ต้องตัดยกแผง"</b>',
 guide="Alikhan A, et al. North American clinical management guidelines for hidradenitis suppurativa, Parts I–II. J Am Acad Dermatol 2019; Grabb and Smith's Plastic Surgery 8th ed. (2020)",
 variants=[
  'หญิงเป็น HS Hurley II มี tract สั้นเส้นเดียวที่ขาหนีบซ้ำที่เดิม → deroofing เปิดหลังคา tract ขูดฐาน แล้วปล่อยหายเอง',
  'ชายเป็น HS รุนแรงที่ฝีเพิ่งแตกมีหนองมากและมีไข้ → ระบายหนองคุมการติดเชื้อก่อน แล้วค่อยวางแผนตัดกว้างเมื่อการอักเสบสงบ',
  'ผู้ป่วย HS ที่ยังสูบบุหรี่วันละซองขอผ่าตัด → แนะนำเลิกบุหรี่ด้วย เพราะบุหรี่สัมพันธ์กับโรครุนแรงและตอบสนองต่อการรักษาไม่ดี',
  'HS รุนแรงที่หนองเรื้อรังจนซีดและ albumin ต่ำ → แก้ภาวะซีดและทุพโภชนาการก่อนผ่าตัดใหญ่'])

mk(Q, 124, ['s8','s9'],
 stem='A healthy 45-year-old man has a warm, red, tender, swollen shin without pus, fever or necrosis. What is the treatment?',
 opts=['Incision and drainage of the swollen area','Outpatient oral cephalexin','Topical antifungal cream to the shin','Admission for intravenous vancomycin','Urgent surgical exploration and debridement'],
 interp='ชายสุขภาพดี ผิวหน้าแข้งบวมแดงร้อนกดเจ็บ ไม่มีหนอง ไม่ fluctuant ไม่มีไข้ ไม่มีเนื้อตาย = nonpurulent cellulitis ระดับเบา → ถามการรักษา ต้องใช้หลักแบ่ง cellulitis เป็นมีหนองหรือไม่มีหนอง แล้วแบ่งความรุนแรงจากอาการทั่วร่างกายและภูมิคุ้มกัน',
 why='Cellulitis คือการอักเสบติดเชื้อของ <b>dermis และไขมันใต้ผิว</b> ขอบผื่นไม่ชัด (ต่างจาก erysipelas ที่อยู่ตื้นกว่าและขอบนูนชัด) เชื้อหลักคือ <b>β-hemolytic streptococci โดยเฉพาะ group A</b> รองลงมาคือ S. aureus เข้าทางรอยแตกของผิว เช่น tinea pedis · IDSA 2014 แบ่ง <b>ไม่มีหนอง vs มีหนอง</b> แล้วแบ่งความรุนแรง: <b>เบา</b> (ไม่มีอาการทั่วร่างกาย) → <b>ยากินแบบผู้ป่วยนอก</b>ที่คลุม streptococci เช่น penicillin V, cephalexin, dicloxacillin หรือ clindamycin · <b>ปานกลาง</b> (มีไข้หรืออาการทั่วร่างกาย) → ยาทางหลอดเลือด เช่น cefazolin หรือ ceftriaxone · <b>รุนแรง</b> (SIRS ร่วมความดันต่ำ ภูมิคุ้มกันต่ำ หรือสงสัยการติดเชื้อชั้นลึก) → vancomycin ร่วม piperacillin-tazobactam และให้ศัลยแพทย์ประเมิน · ให้ยา 5 วัน ขยายถ้ายังไม่ดีขึ้น ยกขาสูง และรักษาแผลหรือเชื้อราที่เป็นทางเข้า · cellulitis ไม่มีหนองจึงไม่มีโพรงให้ระบาย · ชีทหน้า 8 <b>"การรักษาโดยการให้ยาปฏิชีวนะ โดยการรับประทานก็พอเพียง ยกเว้นผู้ป่วยที่มีภูมิคุ้มกันผิดปกติ จะต้องรับผู้ป่วยไว้ในโรงพยาบาลและให้ยาปฏิชีวนะทางหลอดเลือด"</b>',
 wrong={
  'A':'การกรีดระบายใช้เมื่อมีหนองสะสมเป็นฝี (purulent infection) ซึ่งคลำได้ fluctuant หรือเห็นจาก ultrasound — cellulitis ที่ไม่มีหนองไม่มีโพรงให้ระบาย การกรีดเพิ่มแผลโดยไม่ได้ประโยชน์ · จะถูกถ้าชายมีก้อนแดงเจ็บขนาด 4 cm ที่ต้นขา คลำได้ fluctuant ตรงกลาง และ ultrasound พบโพรงหนอง ร่วมกับผิวรอบก้อนแดงเล็กน้อย',
  'C':'ยาฆ่าเชื้อราทาใช้รักษา tinea ซึ่งเป็นผื่นแห้งคันขอบชัดมีขุย ไม่ร้อนไม่บวม — เชื้อราที่ซอกนิ้วเท้าเป็นทางเข้าของ streptococci ได้ จึงควรรักษาร่วมเพื่อลดการเป็นซ้ำ แต่ไม่ใช่การรักษา cellulitis · จะถูกถ้าหญิงมีผื่นวงแหวนคันที่หน้าแข้ง ขอบนูนแดงมีขุย ตรงกลางผิวจางลง ไม่ร้อนไม่เจ็บ และขูดขุยพบ hyphae',
  'D':'การนอนโรงพยาบาลให้ vancomycin ใช้ใน cellulitis ระดับรุนแรงหรือเสี่ยง MRSA เช่น มี SIRS ร่วมความดันต่ำ ภูมิคุ้มกันต่ำ ใช้ยาเสพติดทางหลอดเลือด หรือรักษาด้วยยากินแล้วไม่ดีขึ้น — คนสุขภาพดีไม่มีไข้ไม่จำเป็น · จะถูกถ้าชายฉีดยาเสพติดเข้าหลอดเลือดที่ขา มีผิวบวมแดงลามรอบรอยเข็ม ไข้สูง และชีพจรเร็ว',
  'E':'การผ่าตัดสำรวจและตัดเนื้อตายเร่งด่วนใช้กับ necrotizing soft tissue infection ซึ่งปวดเกินสิ่งที่เห็น ผิวคล้ำ ตุ่มน้ำเลือด ชา หรือมีแก๊สใต้ผิว และมักมี sepsis — โจทย์ไม่มีลักษณะใดเลย · จะถูกถ้าหญิงเบาหวานปวดขามากเกินผื่นที่เห็น มีตุ่มน้ำปนเลือด ผิวชา และคลำได้กรอบแกรบใต้ผิว ร่วมกับความดันต่ำ'},
 trap='คำว่าบวมแดงร้อนชวนให้คิดว่าต้องกรีด หรือต้องรับไว้ให้ยาทางหลอดเลือด · หลักแยก: ดูว่ามีหนองหรือไม่ แล้วดูอาการทั่วร่างกายและภูมิคุ้มกัน — ไม่มีหนอง ไม่มีไข้ ภูมิปกติ คือ cellulitis ระดับเบา รักษาด้วยยากินแบบผู้ป่วยนอก',
 summary=[
  'แกน: nonpurulent cellulitis ระดับเบาในคนภูมิปกติ → ยากินคลุม streptococci แบบผู้ป่วยนอก (ชีทหน้า 8)',
  'เชื้อ: group A streptococci และ S. aureus · ทางเข้าบ่อย: tinea pedis แผลถลอก ขาบวมน้ำเหลือง',
  'IDSA 2014: เบา = ยากิน · ปานกลาง (มีอาการทั่วร่างกาย) = ยาทางหลอดเลือด · รุนแรง = vancomycin + piperacillin-tazobactam + ประเมินการผ่าตัด',
  'รับไว้ในโรงพยาบาล: ภูมิคุ้มกันผิดปกติ (ชีท) · sepsis · ลามเร็ว · กินยาไม่ได้ · ยากินไม่ได้ผล',
  'ให้ยา 5 วัน ขยายถ้ายังไม่ดีขึ้น · ยกขาสูง · รักษาเชื้อราที่เท้าเพื่อลดการเป็นซ้ำ',
  'มีหนองหรือ fluctuant → I&D · ปวดเกินสิ่งที่เห็น ผิวคล้ำ ตุ่มน้ำเลือด → คิดถึง necrotizing infection'],
 opinion='เห็นด้วยกับคำตอบ B ความมั่นใจสูง — ชีทหน้า 8 ให้ยากินพอในคนภูมิปกติ และ IDSA 2014 ให้ยากินแบบผู้ป่วยนอกใน nonpurulent cellulitis ที่ไม่มีอาการทั่วร่างกาย · จุดต่าง: ชีทระบุเชื้อเป็น group A streptococci และ S. aureus เท่ากัน แต่ IDSA เน้นว่า cellulitis ไม่มีหนองเกิดจาก streptococci เป็นหลัก ไม่ต้องคลุม MRSA เป็นประจำ (RCT ปี 2017 พบว่าเพิ่ม TMP-SMX กับ cephalexin ไม่ได้ประโยชน์เพิ่มอย่างมีนัยสำคัญ) ส่วนรูปในชีทหน้า 9 แสดงหลังเท้าบวมคล้ำของ cellulitis',
 mnemonic='<b>"Cellulitis: หนองไหม → ไข้ไหม → ภูมิดีไหม · ไม่ ไม่ ดี = ยากินกลับบ้าน"</b>',
 guide='Stevens DL, et al. Practice guidelines for the diagnosis and management of skin and soft tissue infections: 2014 update by the IDSA. Clin Infect Dis 2014; Sabiston Textbook of Surgery 21st ed. (2022) — Surgical infections',
 variants=[
  'หญิงมีผื่นแดงนูนขอบชัดเจนที่แก้ม ผิวมันเงา พร้อมไข้ → erysipelas จาก group A streptococci ยาหลักคือ penicillin',
  'ชายเป็น cellulitis ที่ขาซ้ำปีละ 3–4 ครั้งแม้รักษาเชื้อราที่เท้าแล้ว → พิจารณาให้ penicillin ป้องกันระยะยาว',
  'หญิงหัวใจล้มเหลวมีผื่นแดงที่หน้าแข้งสองข้างพร้อมกัน ไม่ร้อนไม่ไข้ และขาบวม → stasis dermatitis ไม่ใช่ cellulitis ไม่ต้องให้ยาปฏิชีวนะ',
  'หลังยากิน 3 วัน ผื่นแดงลามเกินเส้นที่ขีดไว้และเริ่มมีไข้ → เปลี่ยนเป็นยาทางหลอดเลือด และตรวจหาฝีหรือการติดเชื้อชั้นลึก'])

mk(Q, 125, ['s8','s9'],
 stem='A 56-year-old man with alcoholic cirrhosis and diabetes has rapidly spreading thigh pain and septic shock. At surgery the fascia is necrotic and the underlying muscle is gray, does not bleed when cut and does not contract when stimulated. What is the most appropriate management?',
 opts=['Repeated radical debridement, broad-spectrum antibiotics and ICU care','A single limited incision and drainage','High-dose intravenous antibiotics without surgery','Hyperbaric oxygen before any surgical debridement','Outpatient oral antibiotics with review of the spreading margin in 48 hours'],
 interp='ชายตับแข็งและเบาหวาน ปวดต้นขาลามเร็วร่วม septic shock ผ่าตัดพบ fascia ตายและกล้ามเนื้อสีเทา กรีดไม่มีเลือดออก กระตุ้นไม่หดตัว = necrotizing soft tissue infection ที่ลงถึงกล้ามเนื้อ (necrotizing myositis) → ถามการรักษาที่เหมาะที่สุด ต้องใช้หลักสามเสาคือผ่าตัดเอาเนื้อตายออกซ้ำ ยาครอบคลุมกว้าง และประคับประคองใน ICU',
 why='Necrotizing soft tissue infection แบ่งตามชั้นที่ติดเชื้อ: <b>necrotizing fasciitis</b> ลามเร็วตามระนาบ fascia และ <b>necrotizing myositis</b> ที่ลงถึงกล้ามเนื้อ ผู้ป่วยมักมีโรคประจำตัว เช่น <b>เบาหวาน ตับแข็ง พิษสุราเรื้อรัง ไตวาย ภูมิคุ้มกันต่ำ</b> เชื้อส่วนใหญ่เป็น<b>หลายชนิดร่วมกัน</b> ทั้ง gram-positive (streptococci, S. aureus, Clostridium) และ gram-negative กับ anaerobe · กล้ามเนื้อที่ตายบอกได้ด้วย <b>4 C: color เทาคล้ำ · consistency เละ · contractility ไม่หดตัว · capacity to bleed ไม่มีเลือดออก</b> · การรักษามี 3 เสาที่ต้องทำพร้อมกัน: <b>(1) aggressive debridement</b> ตัดผิว ไขมัน fascia และกล้ามเนื้อที่ตายจนถึงเนื้อดี แล้ว <b>second look ภายใน 24 ชั่วโมง</b> และผ่าซ้ำจนไม่มีเนื้อตาย · <b>(2) ยาครอบคลุมกว้าง</b> เช่น vancomycin ร่วม piperacillin-tazobactam หรือ carbapenem บวก <b>clindamycin</b> เพื่อยับยั้งการสร้าง toxin · <b>(3) ICU</b> ให้สารน้ำเพียงพอ vasopressor และป้องกันไตวาย · ทุกชั่วโมงที่ผ่าตัดช้าเพิ่มอัตราตาย · ชีทหน้า 9 <b>"ผ่าตัดกำจัดเนื้อตาย (aggressive surgical debridement) โดยจะต้องตัดผิวหนัง ชั้นไขมันใต้ผิวหนังและกล้ามเนื้อที่ติดเชื้อออกทั้งหมด ซึ่งอาจจะต้องมีการผ่าตัดซ้ำหลายครั้ง และให้การดูแลรักษาใน ICU"</b>',
 wrong={
  'B':'การกรีดระบายแผลเดียวใช้กับฝีใต้ผิวที่มีขอบเขตจำกัด — การติดเชื้อเนื้อตายลามไปตามระนาบ fascia และกล้ามเนื้อเกินกว่าที่เห็นบนผิว การกรีดเล็กเหลือเนื้อตายไว้เป็นแหล่งเชื้อและ toxin ช็อกจึงไม่ดีขึ้น · จะถูกถ้าหญิงมีฝีขนาด 3 cm ที่ต้นแขน คลำได้ fluctuant ไม่มีเนื้อตาย ไม่มีไข้ และผิวรอบฝีแดงเพียงเล็กน้อย',
  'C':'ยาปฏิชีวนะทางหลอดเลือดขนาดสูงจำเป็นในทุกราย แต่ยาเข้าไม่ถึงเนื้อที่ไม่มีเลือดเลี้ยง การให้ยาอย่างเดียวในการติดเชื้อเนื้อตายจึงมีอัตราตายใกล้ร้อยเปอร์เซ็นต์ · จะถูกถ้าชายมี cellulitis ที่ขาลามพร้อมไข้และชีพจรเร็ว แต่ความดันปกติ ไม่มีเนื้อตาย ไม่มีตุ่มน้ำเลือด และ CT ไม่พบแก๊สหรือของเหลวตามระนาบ fascia',
  'D':'Hyperbaric oxygen เพิ่มออกซิเจนในเนื้อเยื่อและอาจยับยั้ง Clostridium แต่หลักฐานยังไม่ชัด และ IDSA 2014 ไม่แนะนำให้ใช้เป็นประจำ · ไม่มีสถานการณ์ใดที่ควรให้ hyperbaric oxygen ก่อนผ่าตัดเอาเนื้อตายออกในการติดเชื้อเนื้อตาย เพราะการผ่าตัดช้าเพิ่มอัตราตายโดยตรง และ hyperbaric oxygen เป็นได้เพียงการรักษาเสริมหลังผ่าตัด',
  'E':'ยากินแบบผู้ป่วยนอกพร้อมขีดขอบผื่นแล้วนัดดูใน 48 ชั่วโมงเป็นแนวทางของ cellulitis ระดับเบา — ผู้ป่วยช็อกและพบเนื้อตายในห้องผ่าตัดแล้ว การรอ 48 ชั่วโมงจะถึงแก่ชีวิต · จะถูกถ้าหญิงสุขภาพดีมีผื่นแดงร้อนที่หน้าแข้ง ไม่มีไข้ ไม่มีหนอง ไม่มีเนื้อตาย และกินยาได้'},
 trap='ผู้ป่วยช็อกและตับแข็งชวนให้คิดว่าเสี่ยงเกินกว่าจะผ่าตัดใหญ่ซ้ำ จึงเลือกยาอย่างเดียวหรือแผลเล็ก · หลักแยก: ในการติดเชื้อเนื้อตาย การผ่าตัดเอาเนื้อตายออกคือการแก้ช็อก ยิ่งป่วยหนักยิ่งต้องผ่าเร็ว และต้องกลับมาดูซ้ำจนไม่มีเนื้อตาย',
 summary=[
  'แกน: necrotizing soft tissue infection ลงถึงกล้ามเนื้อ + septic shock → ผ่าตัดเอาเนื้อตายออกซ้ำ + ยาครอบคลุมกว้าง + ICU (ชีทหน้า 9)',
  'ปัจจัยเสี่ยง (ชีทหน้า 8): เบาหวาน ขาดสารอาหาร อ้วน พิษสุรา หลอดเลือดส่วนปลายตีบ มะเร็งเม็ดเลือดขาว ตับแข็ง ไตวาย ภูมิคุ้มกันบกพร่อง',
  'Fournier gangrene = การติดเชื้อเนื้อตายที่อวัยวะเพศภายนอก ฝีเย็บ และผนังหน้าท้อง',
  'เชื้อ: หลายชนิดร่วมกัน gram-positive (GAS, S. aureus, Clostridium) + gram-negative (E. coli, Pseudomonas, Proteus) + Bacteroides',
  'กล้ามเนื้อตาย 4 C: สีเทา · เละ · ไม่หดตัว · ไม่มีเลือดออก',
  'Second look ภายใน 24 ชั่วโมง · clindamycin ยับยั้ง toxin · LRINEC ช่วยสงสัยแต่ใช้ตัดโรคไม่ได้'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ชีทหน้า 9 ระบุครบทั้งการตัดผิว ไขมัน และกล้ามเนื้อที่ติดเชื้อออกทั้งหมด การผ่าตัดซ้ำ ยา broad-spectrum และดูแลใน ICU ตรงกับ IDSA 2014 และ WSES/SIS-E 2018 · สิ่งที่แนวทางปัจจุบันเพิ่ม: second look ภายใน 24 ชั่วโมง การเติม clindamycin เพื่อยับยั้ง toxin ของ streptococci และ Clostridium และไม่ควรให้ hyperbaric oxygen ทำให้การผ่าตัดช้า · ในผู้ป่วยตับแข็งต้องนึกถึง Vibrio vulnificus ด้วยถ้าสัมผัสน้ำทะเลหรือกินอาหารทะเลดิบ',
 mnemonic='<b>"กล้ามเนื้อตาย 4 C (Color, Consistency, Contractility, Capacity to bleed) → ผ่า ผ่าซ้ำ ยากว้าง ICU"</b>',
 guide='Stevens DL, et al. IDSA practice guidelines for skin and soft tissue infections. Clin Infect Dis 2014; Sartelli M, et al. 2018 WSES/SIS-E consensus conference: recommendations for the management of skin and soft-tissue infections. World J Emerg Surg 2018; Sabiston Textbook of Surgery 21st ed. (2022)',
 variants=[
  'ชายตับแข็งเพิ่งกินหอยนางรมดิบ มีตุ่มน้ำปนเลือดที่ขาลามเร็วและช็อก → Vibrio vulnificus ให้ doxycycline ร่วม third-generation cephalosporin และผ่าตัดเร่งด่วน',
  'ชายถูกตะปูตำเท้าแผลลึก ภายในวันเดียวปวดรุนแรง ผิวสีบรอนซ์ น้ำเหลืองสีน้ำตาล และคลำกรอบแกรบ → Clostridium myonecrosis ผ่าตัดด่วน + penicillin ร่วม clindamycin',
  'ครบ 24 ชั่วโมงหลัง debridement ครั้งแรก ผู้ป่วยยังต้องเพิ่มขนาด vasopressor → กลับห้องผ่าตัดหาเนื้อตายที่ยังเหลือ',
  'กล้ามเนื้อขาท่อนล่างตายทุกมัดร่วมช็อกที่ไม่ตอบสนอง → พิจารณา guillotine amputation เพื่อควบคุมแหล่งติดเชื้อ'])

mk(Q, 126, ['s9'],
 stem='A 40-year-old man has a woody jaw swelling with draining sinuses discharging yellow granules. What is the treatment of choice?',
 opts=['External beam radiotherapy to the jaw','Oral itraconazole for six months','Incision and drainage with one week of cloxacillin','Four-drug antituberculous therapy for six months','Prolonged high-dose penicillin'],
 interp='ก้อนแข็งเหมือนไม้ที่ขากรรไกร มีรูหนองหลายรูและพบเม็ดสีเหลืองในหนอง = cervicofacial actinomycosis (lumpy jaw) → ถามยาหลักที่ใช้รักษา ต้องใช้หลักว่า Actinomyces เป็นแบคทีเรีย anaerobe ที่ไวต่อ penicillin แต่ต้องให้ยานานเพราะรอยโรคเป็นพังผืดหนา',
 why='<b>Actinomyces israelii</b> เป็น<b>แบคทีเรีย gram-positive รูปเส้นสาย anaerobe</b> ประจำถิ่นในช่องปาก (แม้ชื่อคล้ายเชื้อรา) ก่อโรคเมื่อเยื่อบุถูกทำลาย เช่น <b>ถอนฟัน ฟันผุ เหงือกอักเสบ</b> · รอยโรคเป็น <b>granulomatous suppurative</b> ก้อนแข็งเหมือนไม้ (woody) <b>ลามข้ามชั้นเนื้อเยื่อ ไม่ไปตามท่อน้ำเหลือง</b> แล้วแตกเป็นรูหนองหลายรู พบที่ศีรษะใบหน้ามากที่สุด · หนองมี <b>sulfur granules</b> สีเหลือง (กลุ่มเส้นสายเชื้อ) ยืนยันด้วยย้อม gram และเพาะเชื้อแบบ anaerobe ซึ่งขึ้นช้า · การรักษาหลักคือ <b>penicillin ขนาดสูงเป็นเวลานาน</b> แบบดั้งเดิมให้ penicillin G ทางหลอดเลือด 2–6 สัปดาห์ ต่อด้วย penicillin V หรือ amoxicillin กิน <b>6–12 เดือน</b> (รอยโรคเล็กที่ผ่าตัดออกได้อาจใช้สั้นกว่า) เพราะพังผืดหนาทำให้ยาเข้าน้อย และเชื้อกลับเป็นซ้ำถ้าหยุดยาเร็ว · ผ่าตัดเมื่อมีฝีลึก เนื้อตาย หรือ sinus เรื้อรัง · แพ้ penicillin ใช้ doxycycline หรือ ceftriaxone · ชีทหน้า 9 <b>"การวินิจฉัยที่เป็น pathognomonic คือ พบ sulfur granules ในหนองที่ส่งตรวจ การรักษาโดยการให้ยา penicillin และ sulfonamides แต่ถ้าเป็นหนองที่อยู่ลึกหรือเป็นแผลเป็นที่มีการติดเชื้อ อาจต้องผ่าตัดร่วมด้วย"</b>',
 wrong={
  'A':'การฉายรังสีเป็นการรักษาหลักของมะเร็งบางชนิดในศีรษะลำคอ ก้อนแข็งเหมือนไม้ของ actinomycosis จึงมักถูกสงสัยว่าเป็นมะเร็ง แต่เม็ดสีเหลืองในหนองบอกว่าเป็นการติดเชื้อ และรังสียิ่งทำลายหลอดเลือดจนติดเชื้อเรื้อรัง · จะถูกถ้าชายมีเลือดกำเดาข้างเดียว หูอื้อ และต่อมน้ำเหลืองที่คอโตโดยไม่มีรูหนอง ผลชิ้นเนื้อเป็น nasopharyngeal carcinoma ระยะต้น',
  'B':'Itraconazole เป็นยาต้านเชื้อรากลุ่ม azole — Actinomyces เป็นแบคทีเรีย ยาต้านเชื้อราจึงไม่ได้ผล · โรคที่มีเม็ดในหนองและรูหนองหลายรูเหมือนกันแต่เกิดจากเชื้อราคือ eumycetoma · จะถูกถ้าชาวนามีก้อนบวมที่เท้าหลังถูกหนามตำนานหลายปี มีรูหนองหลายรูที่ปล่อยเม็ดสีดำ และเพาะเชื้อได้เชื้อรา Madurella',
  'C':'การกรีดระบายร่วม cloxacillin หนึ่งสัปดาห์เป็นการรักษาฝีจาก S. aureus — actinomycosis ต้องได้ penicillin นานหลายเดือน การให้ยาสั้นทำให้กลับเป็นซ้ำ และ cloxacillin ไม่ใช่ยามาตรฐานของ Actinomyces · จะถูกถ้าหญิงมีฝีที่ผิวใต้คางขนาด 2 cm เกิดภายใน 3 วันจากรูขุมขนอักเสบ คลำได้ fluctuant และหนองข้นสีเหลืองไม่มีเม็ด',
  'D':'ยาวัณโรค 4 ตัวนาน 6 เดือนเป็นการรักษาวัณโรคต่อมน้ำเหลืองและ scrofuloderma ซึ่งมีรูหนองหลายรูที่คอเหมือนกัน แต่หนองไม่มี sulfur granules และพบ acid-fast bacilli หรือ caseating granuloma · จะถูกถ้าหญิงมีต่อมน้ำเหลืองที่คอโตช้า ๆ หลายก้อนแตกเป็นรูหนอง พร้อมไข้ต่ำ น้ำหนักลด และ biopsy พบ caseating granuloma'},
 trap='ชื่อ Actinomyces และลักษณะเส้นสายแตกแขนงชวนให้คิดว่าเป็นเชื้อรา และก้อนแข็งเหมือนไม้ชวนให้คิดว่าเป็นมะเร็ง · หลักแยก: sulfur granules ในหนอง + ประวัติฟัน = แบคทีเรีย anaerobe ที่ไวต่อ penicillin แต่ต้องให้ยานานหลายเดือน',
 summary=[
  'แกน: actinomycosis → penicillin ขนาดสูงนาน (ทางหลอดเลือด 2–6 สัปดาห์ แล้วกินต่อ 6–12 เดือน) ± ผ่าตัดฝีลึก',
  'Actinomyces israelii: แบคทีเรีย gram-positive เส้นสาย anaerobe ประจำถิ่นในช่องปาก ไม่ใช่เชื้อรา',
  'ศีรษะใบหน้า 40–60% (ชีทหน้า 9) · ปัจจัยเสี่ยง: ถอนฟัน ฟันผุ เหงือกอักเสบ · ตำแหน่งอื่น: ทรวงอก ช่องท้อง อุ้งเชิงกราน',
  'ลักษณะ: ก้อนแข็งเหมือนไม้ ลามข้ามชั้นเนื้อเยื่อ ไม่ลามตามน้ำเหลือง แตกเป็นรูหนองหลายรู',
  'วินิจฉัย: sulfur granules + gram stain + เพาะเชื้อ anaerobe (ขึ้นช้า ต้องแจ้งห้องปฏิบัติการ)',
  'แพ้ penicillin: doxycycline หรือ ceftriaxone · ชีทเขียน penicillin และ sulfonamides'],
 opinion='เห็นด้วยกับคำตอบ E ความมั่นใจสูง — penicillin เป็นยาหลักทั้งในชีทหน้า 9 และตำราปัจจุบัน · จุดที่ชีทต่างจากปัจจุบัน: ชีทเขียน penicillin ร่วม sulfonamides ซึ่งปัจจุบันไม่ใช่ยาหลักแล้ว และไม่ได้ระบุระยะเวลา ซึ่งตาม Mandell 9e (2020) และ review ของ Valour 2014 ต้องให้ penicillin ขนาดสูงหลายเดือน · อีกจุดคือ sulfur granules ไม่ได้ pathognomonic สมบูรณ์ เพราะพบเม็ดคล้ายกันใน Nocardia, botryomycosis และ mycetoma จึงต้องยืนยันด้วยการย้อมและเพาะเชื้อ',
 mnemonic='<b>"Actinomyces = แบคทีเรียแต่งตัวเป็นเชื้อรา: เม็ดเหลือง ข้ามชั้น ไม่ตามน้ำเหลือง → penicillin นานเป็นเดือน"</b>',
 guide="Valour F, et al. Actinomycosis: etiology, clinical features, diagnosis, treatment, and management. Infect Drug Resist 2014; Mandell, Douglas, and Bennett's Principles and Practice of Infectious Diseases 9th ed. (2020)",
 variants=[
  'หญิงใส่ห่วงคุมกำเนิดนานหลายปี มีก้อนในอุ้งเชิงกรานคล้ายมะเร็งรังไข่ → นึกถึง pelvic actinomycosis เอาห่วงออกและให้ penicillin นาน',
  'ชายติดสุรามีก้อนที่ผนังทรวงอกลามมาจากปอด แตกเป็นรูหนองผ่านช่องซี่โครง → thoracic actinomycosis',
  'ผลเพาะเชื้อจากหนองที่มีเม็ดสีเหลืองรายงานว่าไม่ขึ้นเชื้อหลัง 48 ชั่วโมง → ยังตัด actinomycosis ไม่ได้ เพราะเชื้อขึ้นช้า ต้องเพาะแบบ anaerobe นานถึง 2–3 สัปดาห์',
  'เส้นสายแตกแขนงในหนองย้อม modified acid-fast ติดสี ในผู้ป่วยกินยากดภูมิ → Nocardia รักษาด้วย TMP-SMX'])

mk(Q, 127, ['s9','s10'],
 stem='A 12-year-old boy has several rough, raised, skin-colored papules on his fingers. Paring the surface reveals tiny black dots and pinpoint bleeding. What are the black dots?',
 opts=['Open comedones of acne vulgaris','Ingrown hairs within inflamed follicles','Irregular melanin from acral lentiginous melanoma','Thrombosed capillaries within common warts','Asphalt particles from traumatic tattooing'],
 interp='เด็กชายมีตุ่มนูนสากสีผิวที่นิ้วมือหลายเม็ด เมื่อฝานผิวออกพบจุดดำเล็ก ๆ และจุดเลือดออก = common wart (verruca vulgaris) จาก HPV → ถามว่าจุดดำคืออะไร ต้องใช้หลักโครงสร้างของหูดที่ dermal papilla ยืดยาวและมี capillary ขยายตัวอุดตันอยู่ภายใน',
 why='HPV เข้าสู่ keratinocyte ชั้น basal ผ่านรอยถลอกเล็ก ๆ แล้วเพิ่มจำนวนเมื่อเซลล์เลื่อนขึ้นชั้นบน ทำให้เกิด <b>epidermal hyperplasia · papillomatosis · hyperkeratosis</b> และ <b>koilocyte</b> ในชั้น granular · dermal papilla ที่ยืดยาวขึ้นมาในตุ่มมี <b>capillary ขยายตัวและอุดตันด้วยลิ่มเลือด</b> เมื่อมองจากผิวหรือฝานชั้น keratin ออกจะเห็นเป็น<b>จุดดำเล็ก ๆ</b> และมีจุดเลือดออก (pinpoint bleeding) จาก capillary ที่ยังเปิดอยู่ · ลักษณะนี้ช่วยแยก <b>plantar wart จากตาปลา (corn)</b>: หูดทำให้ลายผิวหนัง (dermatoglyphics) ขาด มีจุดดำ เจ็บเมื่อบีบด้านข้าง ส่วนตาปลาลายผิวต่อเนื่อง มีแกนใสตรงกลาง เจ็บเมื่อกดตรง · ชนิดหูดตามตำแหน่งและ HPV type: common wart (HPV 2, 4) ที่นิ้วมือนิ้วเท้า · plantar wart (HPV 1) ที่ฝ่ามือฝ่าเท้า · flat wart (HPV 3, 10) ที่ใบหน้า · condyloma acuminata (HPV 6, 11) ที่อวัยวะเพศและรอบทวาร · ในเด็กราวสองในสามหายเองภายใน 2 ปี · ชีทหน้า 9 <b>"อาจพบเส้นเลือดอุดตันอยู่ตรงกลางรอยโรคเห็นเป็นจุดสีดำ ส่วนใหญ่พบที่นิ้วมือและนิ้วเท้า เรียกว่า “common wart” (verrucus vulgaris)"</b>',
 wrong={
  'A':'Open comedone (สิวหัวดำ) คือรูขุมขนที่อุดด้วย keratin และไขมัน ส่วนบนเปิดสัมผัสอากาศจน melanin และไขมันถูก oxidize เป็นสีดำ พบที่หน้า จมูก หน้าผาก หลัง ซึ่งมีต่อมไขมันมาก ไม่ใช่ตุ่มสากที่นิ้วมือ · จะถูกถ้าเด็กหญิงวัยรุ่นมีจุดดำเล็ก ๆ จำนวนมากที่รูขุมขนบริเวณจมูกและหน้าผาก ร่วมกับตุ่มแดงอักเสบ',
  'B':'ขนคุดเกิดจากเส้นขนที่ม้วนกลับแทงเข้าผิวทำให้รูขุมขนอักเสบ เห็นเป็นเส้นหรือจุดดำใต้ตุ่มแดง พบในบริเวณที่โกนหรือถอนขน เช่น เครา ขาหนีบ ขา — นิ้วมือเด็กไม่ใช่ตำแหน่งที่มีขนแบบนี้ · จะถูกถ้าชายผมหยิกโกนหนวดทุกวัน มีตุ่มแดงคันที่คางและคอ แต่ละตุ่มมีเส้นขนสีดำม้วนอยู่ใต้ผิว (pseudofolliculitis barbae)',
  'C':'Acral lentiginous melanoma เป็นชนิดที่พบบ่อยที่สุดในคนเอเชีย เห็นเป็นปื้นสีน้ำตาลดำแบน ขอบไม่เรียบ สีไม่สม่ำเสมอที่ฝ่ามือฝ่าเท้าหรือใต้เล็บ ไม่ใช่ตุ่มสากหลายเม็ด และพบน้อยมากในเด็ก · จะถูกถ้าหญิงอายุ 65 ปีมีปื้นสีดำแบนที่ส้นเท้าขนาด 1.5 cm ขยายขึ้นในหนึ่งปี ขอบหยัก สีไม่สม่ำเสมอ และ dermoscopy พบ parallel ridge pattern',
  'E':'Traumatic tattoo เกิดจากเศษยางมะตอยหรือดินฝังในชั้น dermis หลังแผลถลอก เห็นเป็นจุดสีดำเทาฝังอยู่ในผิวเรียบ ไม่ใช่ตุ่มนูนสาก และไม่มีเลือดออกเมื่อฝานผิว · จะถูกถ้าเด็กชายล้มจากจักรยานไถลบนถนน หลังแผลถลอกที่เข่าหายเหลือจุดดำเทาจำนวนมากฝังในผิวเรียบ ซึ่งป้องกันได้ด้วยการขัดล้างเศษออกตั้งแต่แรก'},
 trap='จุดดำบนผิวชวนให้คิดถึงเม็ดสี ทั้ง melanin ของ melanoma หรือสิวหัวดำ · หลักแยก: ตุ่มสากหลายเม็ดในเด็กที่นิ้ว เมื่อฝานแล้วมีจุดเลือดออก = capillary ที่อุดตันในหูด ไม่ใช่เม็ดสี และลายผิวขาดตรงรอยโรค',
 summary=[
  'แกน: จุดดำในหูด = capillary ใน dermal papilla ที่ขยายและอุดตัน · ฝานแล้วมีจุดเลือดออก (ชีทหน้า 9)',
  'HPV ติดเชื้อ keratinocyte ผ่านรอยถลอก · พบบ่อยในเด็กและวัยรุ่น · ติดต่อโดยการสัมผัส',
  'ชนิด: common (นิ้วมือ นิ้วเท้า) · plantar (ฝ่ามือฝ่าเท้า) · flat wart (ใบหน้า แบนกว่า) · condyloma acuminata (vulva, anus, scrotum)',
  'Plantar wart vs corn: หูดลายผิวขาด มีจุดดำ เจ็บเมื่อบีบข้าง · ตาปลาลายผิวต่อ แกนใส เจ็บเมื่อกดตรง',
  'พยาธิ: papillomatosis · hyperkeratosis · koilocyte · capillary ขยายใน dermal papilla',
  'ในเด็กราว 2 ใน 3 หายเองภายใน 2 ปี จึงเลือกวิธีที่ไม่ทิ้งแผลเป็นก่อน'],
 opinion='เห็นด้วยกับคำตอบ D ความมั่นใจสูง — ชีทหน้า 9 ระบุตรงว่าจุดสีดำกลางรอยโรคคือเส้นเลือดอุดตัน ตรงกับพยาธิสภาพในตำราผิวหนัง · จุดที่ต่างเล็กน้อย: ชีทเขียนว่า HPV ติดเชื้อ keratinocyte ชั้น stratum granulosum แต่ตำราปัจจุบัน (Bolognia Dermatology 4e, 2018) อธิบายว่าเชื้อเข้าสู่ basal keratinocyte ก่อน ส่วนชั้น granular เป็นที่ไวรัสเพิ่มจำนวนเต็มที่และเห็น koilocyte · ชีทหน้า 9 จัดหูดที่ฝ่ามือไว้กับ plantar wart ซึ่งตำราส่วนใหญ่เรียกรวมว่า palmoplantar wart',
 mnemonic='<b>"หูดมีจุดดำ = เส้นเลือดอุด ไม่ใช่สี · ฝานแล้วเลือดซึม ลายผิวขาด"</b>',
 guide='Bolognia JL, et al. Dermatology 4th ed. (2018) — Human papillomaviruses; Sterling JC, et al. British Association of Dermatologists guidelines for the management of cutaneous warts 2014. Br J Dermatol 2014',
 variants=[
  'ตุ่มแข็งที่ฝ่าเท้าใต้หัวกระดูก metatarsal ฝานแล้วเห็นแกนใสตรงกลาง ลายผิวต่อเนื่องผ่านรอยโรค ไม่มีจุดเลือดออก → corn ไม่ใช่หูด แก้ที่แรงกด',
  'ติ่งเนื้อยื่นเป็นแท่งเล็ก ๆ คล้ายนิ้วที่เปลือกตาและริมฝีปากของผู้ใหญ่ → filiform wart จาก HPV',
  'หูดรอบเล็บที่ลามลงใต้เล็บในคนกัดเล็บ → periungual wart รักษายากและเป็นซ้ำบ่อย',
  'ผู้รับการปลูกถ่ายไตมีหูดจำนวนมากที่มือ และก้อนหนึ่งโตเร็วแข็งเป็นแผล → biopsy แยก SCC เพราะภูมิคุ้มกันต่ำเพิ่มความเสี่ยง'])

mk(Q, 128, ['s10'],
 stem='A 22-year-old woman has a painful plantar wart that persisted after 12 weeks of salicylic acid and three sessions of cryotherapy. She asks about the general approach to warts. Which statement is correct?',
 opts=['Excision follows failed destructive methods, and warts often recur','Wide excision is first-line because removing the wart prevents recurrence','Clearance of the visible wart means the virus has been eradicated','Oral antibiotics are needed because plantar warts are bacterial infections','Radiotherapy is the standard option for warts resistant to cryotherapy'],
 interp='หญิงมี plantar wart ที่เจ็บ ไม่หายหลังทา salicylic acid 12 สัปดาห์และจี้เย็น 3 ครั้ง แล้วถามหลักการรักษาหูดโดยรวม → ถามข้อความที่ถูกเรื่องลำดับการรักษาหูด ต้องใช้หลักว่าหูดเป็นการติดเชื้อไวรัสที่ไม่มียาฆ่าเชื้อโดยตรง รักษาด้วยการทำลายรอยโรค การผ่าตัดเป็นทางเลือกท้าย และเป็นซ้ำบ่อย',
 why='หูดเกิดจาก <b>HPV</b> ซึ่งไม่มียาต้านไวรัสจำเพาะ การรักษาทุกวิธีจึงเป็นการ<b>ทำลายเนื้อเยื่อที่ติดเชื้อ</b>หรือกระตุ้นภูมิคุ้มกันให้กำจัดเอง · <b>แนวแรก</b>: salicylic acid ทาทุกวันนาน 12 สัปดาห์ร่วมกับขูดผิวที่หนาออก และ <b>cryotherapy ด้วยไนโตรเจนเหลว</b>ทุก 2–3 สัปดาห์ ได้ผลใกล้เคียงกัน · <b>แนวที่สอง</b>เมื่อไม่ได้ผล: จี้ไฟฟ้าร่วมขูด (electrocautery with curettage), laser, ทา 5-FU หรือ imiquimod, ฉีด bleomycin หรือ candida antigen เข้ารอยโรค, immunotherapy ด้วย DPCP · <b>excision</b> ใช้เมื่อวิธีอื่นไม่ได้ผลเท่านั้น และต้อง<b>ระวังที่ฝ่าเท้า</b>เพราะแผลเป็นบนจุดลงน้ำหนักอาจเจ็บถาวรกว่าหูดเอง · ทุกวิธี<b>เป็นซ้ำได้บ่อย</b> เพราะ HPV แฝงอยู่ในผิวที่ดูปกติรอบรอยโรค · condyloma ที่อวัยวะเพศใช้ podophyllotoxin, imiquimod, จี้เย็น หรือผ่าตัด · ชีทหน้า 10 <b>"การรักษาสามารถทำได้หลายวิธีคือ ทาด้วย salicylic acid, podophyllum, จี้ด้วยไนโตรเจนเหลว และการจี้ด้วยไฟฟ้า (Electrocautery) ส่วนการผ่าตัด excision จะใช้เมื่อการรักษาชนิดอื่นไม่ได้ผล เกิดกลับเป็นซ้ำได้บ่อย"</b>',
 wrong={
  'B':'การตัดหูดกว้างเป็นแนวแรกขัดกับหลักการรักษา เพราะหูดเป็นรอยโรค benign ที่ส่วนใหญ่หายเองหรือหายด้วยวิธีทำลายที่ไม่ทิ้งแผลเป็น และการตัดกว้างก็ไม่ได้ป้องกันการเป็นซ้ำ · ไม่มีสถานการณ์ใดที่การตัดออกกว้างป้องกันหูดเป็นซ้ำได้แน่นอน เพราะ HPV แฝงอยู่ในผิวปกติรอบ ๆ และหูดอาจขึ้นใหม่ในแผลเป็นที่เจ็บกว่าเดิม โดยเฉพาะที่ฝ่าเท้า',
  'C':'การที่หูดหายไปจากสายตาไม่ได้แปลว่าเชื้อหมด HPV ยังแฝงในเซลล์ชั้น basal ของผิวที่ดูปกติรอบรอยโรค จึงเป็นซ้ำที่เดิมหรือข้างเคียงได้หลายเดือนต่อมา · ไม่มีสถานการณ์ใดที่ใช้การหายของรอยโรคที่มองเห็นเป็นหลักฐานว่าไวรัสถูกกำจัดหมด เพราะยังไม่มีการรักษาใดกำจัด HPV แฝงได้ และนี่คือเหตุผลที่หูดเป็นซ้ำบ่อย',
  'D':'หูดเกิดจากไวรัส HPV ไม่ใช่แบคทีเรีย ยาปฏิชีวนะกินจึงไม่มีบทบาทต่อตัวหูด ใช้ได้เฉพาะเมื่อแผลหลังจี้หรือผ่าตัดติดเชื้อแบคทีเรียซ้ำซ้อน · ไม่มีสถานการณ์ใดที่ plantar wart จัดเป็นการติดเชื้อแบคทีเรียที่ต้องรักษาด้วยยาปฏิชีวนะกิน เพราะสาเหตุคือ HPV type 1, 2, 4 ที่ติดเชื้อ keratinocyte',
  'E':'การฉายรังสีไม่ใช่การรักษาหูด เพราะหูดเป็นการติดเชื้อไวรัสที่ benign ส่วนรังสีทำให้ผิวขาดเลือด เป็นพังผืด และเสี่ยงมะเร็งในระยะยาว ซึ่งร้ายแรงกว่าโรคเดิม · ไม่มีสถานการณ์ใดที่แนวทางปัจจุบันใช้รังสีเป็นมาตรฐานของหูดที่ดื้อต่อการจี้เย็น เพราะยังมีวิธีแนวที่สองอีกหลายวิธี เช่น จี้ไฟฟ้า laser ยาทา และการฉีดยาเข้ารอยโรค'},
 trap='เมื่อจี้เย็นและยาทาไม่ได้ผล ชวนให้คิดว่าการตัดออกกว้างคือทางเดียวที่หายขาด · หลักแยก: หูดเป็นไวรัสที่แฝงในผิวรอบรอยโรค ไม่มีวิธีใดรับประกันว่าไม่เป็นซ้ำ การผ่าตัดจึงเป็นทางเลือกท้าย โดยเฉพาะที่ฝ่าเท้าที่แผลเป็นเจ็บถาวร',
 summary=[
  'แกน: รักษาหูดด้วยวิธีทำลายก่อน → excision เมื่อวิธีอื่นไม่ได้ผล · เป็นซ้ำบ่อย (ชีทหน้า 10)',
  'แนวแรก: salicylic acid 12 สัปดาห์ร่วมขูดผิวหนา · cryotherapy ไนโตรเจนเหลวทุก 2–3 สัปดาห์',
  'แนวที่สอง: electrocautery ร่วม curettage · laser · 5-FU หรือ imiquimod ทา · bleomycin หรือ candida antigen ฉีดเข้ารอยโรค',
  'ฝ่าเท้า: เลี่ยงผ่าตัดถ้าทำได้ เพราะแผลเป็นบนจุดลงน้ำหนักเจ็บถาวร',
  'Condyloma acuminata: podophyllotoxin, imiquimod, จี้เย็น, ผ่าตัด · ป้องกันด้วยวัคซีน HPV ที่ครอบคลุม type 6, 11',
  'เป็นซ้ำเพราะ HPV แฝงในผิวที่ดูปกติรอบรอยโรค ยังไม่มีวิธีใดกำจัดเชื้อแฝงได้'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ชีทหน้า 10 ระบุลำดับการรักษาและการเป็นซ้ำตรงตัว · จุดที่แนวทางปัจจุบันต่างจากชีท: BAD guideline 2014 ไม่แนะนำผ่าตัดตัดหูดเป็นประจำเพราะแผลเป็นและอัตราเป็นซ้ำ โดยเฉพาะที่ฝ่าเท้า และให้ทางเลือกแนวที่สองอีกหลายวิธีที่ชีทไม่ได้กล่าวถึง เช่น ฉีด bleomycin เข้ารอยโรค หรือ immunotherapy ส่วน podophyllum ในชีทปัจจุบันใช้ในรูป podophyllotoxin สำหรับหูดที่อวัยวะเพศเป็นหลัก ไม่ใช่หูดที่มือหรือเท้า',
 mnemonic='<b>"หูด: ทา → จี้เย็น → จี้ไฟ → ตัดท้ายสุด · ไวรัสแฝง = กลับมาได้บ่อย"</b>',
 guide='Sterling JC, et al. British Association of Dermatologists guidelines for the management of cutaneous warts 2014. Br J Dermatol 2014; Kwok CS, et al. Topical treatments for cutaneous warts. Cochrane Database Syst Rev 2012',
 variants=[
  'ชายมีหูดหงอนไก่หลายก้อนรอบทวาร → ส่องตรวจในทวารหนักด้วย และตรวจคัดกรองโรคติดต่อทางเพศสัมพันธ์อื่น',
  'เด็ก 6 ขวบมีหูดเม็ดเดียวที่นิ้วไม่เจ็บ ผู้ปกครองกลัวการจี้ → รอดูได้ เพราะส่วนใหญ่หายเองภายใน 2 ปี',
  'หญิงตั้งครรภ์มี condyloma ที่ปากช่องคลอด → เลี่ยง podophyllin และ imiquimod เลือกจี้เย็นหรือ trichloroacetic acid',
  'หูดที่ฝ่าเท้าหลายสิบเม็ดรวมเป็นแผ่น (mosaic wart) ไม่ตอบสนองการจี้เย็น → ใช้วิธีแนวที่สองแทนการตัดออกทั้งแผ่น'])

mk(Q, 129, ['s10', 61],
 stem='A 5-year-old girl has many dome-shaped, umbilicated, skin-colored 3-mm papules on her trunk. What causes them?',
 opts=['Herpes simplex virus type 1','Varicella-zoster virus','Molluscum contagiosum poxvirus','Staphylococcus aureus','Human papillomavirus types 6 and 11'],
 interp='เด็กหญิงมีตุ่มรูปโดมสีผิวขนาด 3 mm หลายเม็ดที่ลำตัว ตรงกลางบุ๋ม = molluscum contagiosum (หูดข้าวสุก) → ถามเชื้อก่อโรค ต้องใช้หลักว่าตุ่มโดมผิวเรียบตรงกลางบุ๋ม (umbilicated) เป็นลักษณะเฉพาะของ poxvirus ไม่ใช่ HPV ที่ทำให้หูดผิวขรุขระ',
 why='<b>Molluscum contagiosum</b> เกิดจาก <b>molluscum contagiosum virus</b> ซึ่งเป็น <b>DNA virus ในกลุ่ม poxvirus</b> ติดเชื้อเฉพาะ keratinocyte ของผิวหนัง · รอยโรคเป็น <b>papule รูปโดมขนาด 2–5 mm สีผิวหรือสีมุก ผิวเรียบ ตรงกลางบุ๋ม (umbilicated)</b> บีบแล้วมีเนื้อขาวคล้ายข้าวสุกออกมา ทางพยาธิพบ intracytoplasmic inclusion ขนาดใหญ่ (<b>molluscum body</b>) · ติดต่อทางการสัมผัสผิว ของใช้ร่วม สระว่ายน้ำ และลามตัวเองจากการเกา · <b>เด็ก</b>: ใบหน้า ลำตัว แขนขา · <b>ผู้ใหญ่</b>: อวัยวะเพศ ติดทางเพศสัมพันธ์ · มักไม่พบที่ฝ่ามือฝ่าเท้า · ในเด็กภูมิปกติหายเองภายใน 6–12 เดือนถึงไม่กี่ปี ก่อนหายมักแดงอักเสบรอบตุ่ม (BOTE sign) · รักษาเมื่อมีอาการหรือผู้ปกครองต้องการ: curettage, จี้ไนโตรเจนเหลว, CO₂ laser, cantharidin · รอยโรคใหญ่หรือจำนวนมากบนหน้าผู้ใหญ่ → ตรวจหา HIV · ชีทหน้า 10 <b>"มีลักษณะเป็น papules รูปโดมขนาด 2-5 มิลลิเมตร ตรงกลางบุ๋มลง (umbilicated) สีเหมือนผิวหนัง"</b> และสไลด์หน้า 61 ตัวพิมพ์ <b>"Viral infections: Human papilloma virus · Pox virus · Herpes virus"</b>',
 wrong={
  'A':'HSV ทำให้ตุ่มน้ำใสเล็ก ๆ เป็นกลุ่มบนฐานแดง ปวดแสบ แตกเป็นแผลตื้นแล้วตกสะเก็ด และเป็นซ้ำที่เดิม ไม่ใช่ตุ่มเนื้อแข็งรูปโดมสีผิว แม้ตุ่มน้ำของ herpes อาจมีรอยบุ๋มตรงกลางได้เช่นกัน · จะถูกถ้าเด็กชายมีตุ่มน้ำใสเป็นกลุ่มที่ริมฝีปากล่าง มีอาการแสบนำมาก่อน 1 วัน และเคยเป็นที่เดิมหลายครั้งเมื่อมีไข้',
  'B':'VZV ทำให้อีสุกอีใส: ตุ่มน้ำหลายระยะพร้อมกัน (แดง ตุ่มน้ำ สะเก็ด) กระจายจากลำตัว ร่วมกับไข้และคัน ตุ่มน้ำอาจบุ๋มกลางได้แต่หายใน 1–2 สัปดาห์ ไม่ใช่ตุ่มแข็งที่อยู่นานเป็นเดือน · จะถูกถ้าเด็กหญิงที่ไม่เคยได้วัคซีนมีไข้ต่ำ แล้วมีผื่นตุ่มน้ำคันหลายระยะพร้อมกันกระจายทั่วลำตัวและหนังศีรษะภายในสองวัน',
  'D':'S. aureus ทำให้ impetigo (สะเก็ดสีน้ำผึ้ง หรือตุ่มน้ำพองแตกง่าย) folliculitis และ furuncle ซึ่งเป็นตุ่มหนองหรือแผลสะเก็ด ไม่ใช่ตุ่มโดมผิวเรียบที่ไม่อักเสบ แต่อาจติดเชื้อซ้ำบนตุ่ม molluscum ที่ถูกเกาได้ · จะถูกถ้าเด็กชายมีแผลถลอกรอบจมูกและปากที่ปกคลุมด้วยสะเก็ดสีเหลืองน้ำผึ้ง ลามเร็วภายในหนึ่งสัปดาห์',
  'E':'HPV 6 และ 11 ทำให้ condyloma acuminata ที่อวัยวะเพศและรอบทวาร เป็นติ่งเนื้อผิวขรุขระคล้ายดอกกะหล่ำ ไม่มีรอยบุ๋มกลาง — ชีทเขียนสาเหตุของ molluscum เป็น HPV 6 และ 11 ซึ่งคลาดเคลื่อน · จะถูกถ้าชายมีติ่งเนื้อนุ่มผิวขรุขระหลายติ่งรอบทวาร คล้ายดอกกะหล่ำ ไม่เจ็บ และมีคู่นอนหลายคน'},
 trap='ตุ่มเล็กหลายเม็ดบนผิวเด็กชวนให้คิดว่าเป็นหูดจาก HPV และชีทหน้า 10 เองก็เขียนว่าเกิดจาก HPV 6 และ 11 · หลักแยก: ตุ่มโดมผิวเรียบเป็นมันมีรอยบุ๋มตรงกลาง = poxvirus ส่วนหูด HPV ผิวขรุขระ ไม่มีรอยบุ๋ม',
 summary=[
  'แกน: molluscum contagiosum เกิดจาก molluscum contagiosum virus (poxvirus) ไม่ใช่ HPV',
  'ตุ่มโดม 2–5 mm สีผิว ผิวเรียบเป็นมัน ตรงกลางบุ๋ม · บีบมีเนื้อขาวคล้ายข้าวสุก (ชีทหน้า 10)',
  'ตำแหน่ง: เด็ก — หน้า ลำตัว แขนขา · ผู้ใหญ่ — อวัยวะเพศ · มักไม่พบที่ฝ่ามือฝ่าเท้า',
  'ติดต่อ: สัมผัสผิว ของใช้ร่วม สระว่ายน้ำ ลามตัวเองจากการเกา · ผู้ใหญ่ที่อวัยวะเพศ = โรคติดต่อทางเพศสัมพันธ์',
  'รักษา: curettage, จี้ไนโตรเจนเหลว, CO₂ laser (ชีท) · cantharidin · ในเด็กหายเองได้ภายในหลายเดือนถึงไม่กี่ปี',
  'สไลด์หน้า 61 จัด viral infections ของผิวเป็น 3 กลุ่ม: HPV · poxvirus · herpesvirus'],
 opinion='เห็นด้วยกับคำตอบ C ความมั่นใจสูงมาก — molluscum contagiosum virus เป็น poxvirus ตามตำราทุกเล่ม และสไลด์หน้า 61 ก็แยก Pox virus เป็นกลุ่มของตัวเอง · <b>ชีทหน้า 10 เขียนผิดว่า molluscum เกิดจาก HPV types 6 และ 11</b> ซึ่งเป็นสาเหตุของ condyloma acuminata ไม่ใช่ molluscum ส่วนลักษณะรอยโรค ตำแหน่ง และการรักษาในชีทนอกนั้นถูกต้อง · ปัจจุบัน FDA รับรอง cantharidin ทา (2023) และ berdazimer gel (2024) สำหรับ molluscum ซึ่งชีทยังไม่ได้กล่าวถึง',
 mnemonic='<b>"Molluscum = ตุ่มมุกบุ๋มกลาง = Pox · หูดขรุขระ = HPV"</b>',
 guide='Bolognia JL, et al. Dermatology 4th ed. (2018) — Poxviruses; American Academy of Pediatrics. Red Book: 2024–2027 Report of the Committee on Infectious Diseases — Molluscum contagiosum',
 variants=[
  'ผู้ใหญ่ติดเชื้อ HIV มีตุ่ม molluscum ขนาดเกิน 1 cm จำนวนมากที่ใบหน้า → บ่งชี้ภูมิคุ้มกันต่ำมาก การเริ่ม antiretroviral therapy ทำให้รอยโรคยุบลง',
  'ตุ่ม molluscum ที่มีมาหลายเดือนเริ่มบวมแดงคล้ายติดเชื้อโดยไม่มีไข้ → มักเป็นสัญญาณกำลังจะหาย (BOTE sign) ไม่ต้องให้ยาปฏิชีวนะ',
  'เด็กมี molluscum ที่ขอบเปลือกตาร่วมกับตาแดงเรื้อรังข้างเดียว → follicular conjunctivitis จาก molluscum ต้องเอารอยโรคที่เปลือกตาออก'])

mk(Q, 130, ['s11'],
 stem='A 26-year-old woman has more than 80 moles, many of them 6 to 9 mm with irregular borders and variegated color. None has changed recently, and her mother had melanoma. What is the most appropriate management?',
 opts=['Prophylactic excision of every mole on her trunk and limbs','Total-body photography and biopsy of changing moles','Laser ablation of all atypical moles without histology','Reassurance and discharge from follow-up','Review only when a mole bleeds or ulcerates'],
 interp='หญิงอายุน้อยมีไฝมากกว่า 80 เม็ด หลายเม็ดขนาด 6–9 mm ขอบไม่เรียบ สีหลากหลาย ยังไม่มีเม็ดใดเปลี่ยนแปลง และแม่เป็น melanoma = dysplastic nevus หลายเม็ดร่วมประวัติครอบครัว (atypical mole syndrome) → ถามการดูแล ต้องใช้หลักว่าตัดได้ไม่หมด จึงติดตามด้วยภาพถ่ายและตัดชิ้นเนื้อเฉพาะเม็ดที่เปลี่ยน',
 why='<b>Dysplastic (atypical) nevus</b> เป็นไฝที่ไม่มีแต่กำเนิด เริ่มพบในวัยเด็ก มีลักษณะ <b>ABCD</b> — ไม่สมมาตร ขอบไม่ชัด สีไม่สม่ำเสมอ และขนาดใหญ่ (ชีทใช้ &gt; 8 mm) · โอกาสเป็น melanoma ตามชีท <b>~6% เมื่อไม่มีประวัติครอบครัว และ ~15% เมื่อมี</b> แต่ความเสี่ยงของไฝแต่ละเม็ดต่ำมาก และ melanoma ส่วนใหญ่เกิดขึ้นใหม่บนผิวปกติ ไม่ได้เกิดจากไฝเดิม การ<b>ตัดไฝทุกเม็ดจึงทำไม่ได้และไม่ได้ป้องกัน</b> · แนวทางคือ<b>เฝ้าระวังอย่างเป็นระบบ</b>: <b>total-body photography</b> เป็นภาพตั้งต้น ร่วมกับ <b>sequential digital dermoscopy</b> ทุก 3–6 เดือนในระยะแรก ตรวจผิวด้วยตนเองทุกเดือน และป้องกันแสงแดด · ไฝเม็ดใดที่<b>เปลี่ยนแปลง</b>หรือดูต่างจากเม็ดอื่นชัด (ugly duckling sign) → <b>excisional biopsy</b> ขอบ 1–3 mm ทั้งก้อน ไม่ใช้ shave หรือ laser เพราะต้องวัดความหนา · ญาติสายตรงควรได้ตรวจผิวด้วย · ชีทหน้า 11 <b>"ไม่สามารถตัดได้หมด จะต้องถ่ายรูปในการติดตาม (total-body photography) ถ้าไฝเม็ดใดมีการเปลี่ยนแปลงจะต้องได้รับการตัดชิ้นเนื้อตรวจ (biopsy)"</b>',
 wrong={
  'A':'การตัดไฝล่วงหน้าทุกเม็ดดูเหมือนตัดความเสี่ยงทิ้ง แต่ melanoma ราว 70% เกิดขึ้นใหม่บนผิวปกติ ไฝแต่ละเม็ดมีโอกาสกลายต่ำมาก และการตัด 80 เม็ดทิ้งแผลเป็นจำนวนมากโดยไม่ลดการตายจาก melanoma · ไม่มีสถานการณ์ใดที่แนวทางแนะนำตัดไฝทุกเม็ดล่วงหน้าในคนที่มีไฝจำนวนมาก เพราะชีทเองระบุว่าตัดได้ไม่หมด และการเฝ้าระวังให้ผลดีกว่า',
  'C':'Laser ทำลายเม็ดสีโดยไม่มีชิ้นเนื้อให้พยาธิแพทย์ตรวจ หากไฝนั้นเป็น melanoma อยู่แล้วจะวินิจฉัยไม่ได้และวัดความหนาไม่ได้ เม็ดสีที่กลับมาใหม่ยังทำให้ติดตามด้วย dermoscopy ยากขึ้น · ไม่มีสถานการณ์ใดที่ควรยิง laser ทำลายไฝที่มีลักษณะ atypical โดยไม่ได้ชิ้นเนื้อ เพราะไฝกลุ่มนี้ต้องแยก melanoma ด้วยพยาธิวิทยาก่อน',
  'D':'การให้ความมั่นใจแล้วไม่นัดติดตามเหมาะกับคนความเสี่ยงต่ำ — ไฝ atypical จำนวนมากร่วมกับแม่เป็น melanoma เป็นกลุ่มเสี่ยงสูงที่ต้องติดตามตลอด · จะถูกถ้าชายอายุ 30 ปีไม่มีประวัติครอบครัว มีไฝ 15 เม็ด ทุกเม็ดกลมเล็กกว่า 5 mm ขอบเรียบสีเดียวและไม่เคยเปลี่ยนแปลง ซึ่งแนะนำเพียงตรวจผิวด้วยตนเองและป้องกันแสงแดด',
  'E':'เลือดออกและแผลเป็นอาการของ melanoma ที่มักหนาแล้ว การรอให้ถึงตอนนั้นจึงพลาดช่วงที่ตัดหายขาดได้ด้วยการผ่าตัดเล็ก · ไม่มีสถานการณ์ใดที่ควรรอให้ไฝมีเลือดออกหรือเป็นแผลก่อนจึงตรวจในคนที่มีไฝ atypical เพราะการเปลี่ยนแปลงของขนาด รูปร่าง หรือสี (Evolving) เป็นข้อบ่งชี้ biopsy ที่เกิดก่อนเลือดออกนาน'},
 trap='ไฝ atypical จำนวนมากร่วมประวัติแม่เป็น melanoma ฟังน่ากลัวจนชวนให้ตัดทุกเม็ด หรือกลับกันคือคิดว่าไม่มีเม็ดใดเปลี่ยนจึงปล่อยได้ · หลักแยก: ความเสี่ยงสูงอยู่ที่ตัวผู้ป่วย ไม่ใช่ที่ไฝแต่ละเม็ด จึงเฝ้าระวังทั้งตัวด้วยภาพถ่ายและตัดเฉพาะเม็ดที่เปลี่ยน',
 summary=[
  'แกน: dysplastic nevus จำนวนมาก + ประวัติครอบครัว → total-body photography ติดตาม + biopsy เม็ดที่เปลี่ยนแปลง (ชีทหน้า 11)',
  'Dysplastic nevus: ไม่มีแต่กำเนิด เริ่มวัยเด็ก · ABCD (ชีท D &gt; 8 mm) · melanoma ~6% ไม่มีประวัติครอบครัว · ~15% มีประวัติครอบครัว',
  'Melanoma ราว 70% เกิดใหม่บนผิวปกติ → ตัดไฝทุกเม็ดไม่ลดความเสี่ยง',
  'เฝ้าระวัง: ภาพถ่ายทั้งตัว + digital dermoscopy ซ้ำ + ตรวจผิวด้วยตนเองทุกเดือน + ป้องกันแดด',
  'Biopsy: excisional ขอบ 1–3 mm ทั้งก้อน ไม่ shave ไม่ laser · ข้อบ่งชี้: เปลี่ยนแปลง (Evolving) หรือ ugly duckling',
  'ความเสี่ยงอยู่ที่ตัวคน: ไฝจำนวนมาก (&gt; 50–100 เม็ด) และไฝ atypical หลายเม็ดเพิ่มความเสี่ยง melanoma หลายเท่า'],
 opinion='เห็นด้วยกับคำตอบ B ความมั่นใจสูง — ชีทหน้า 11 ให้ติดตามด้วย total-body photography และตัดชิ้นเนื้อเม็ดที่เปลี่ยนแปลงตรงตามโจทย์ และสอดคล้องกับตำราผิวหนังปัจจุบัน (Bolognia 4e, 2018) ที่แนะนำภาพถ่ายร่วม dermoscopy ในผู้ที่มีไฝจำนวนมาก · จุดต่าง: ชีทใช้ D &gt; 8 mm ขณะที่เกณฑ์ ABCDE ทั่วไปใช้ &gt; 6 mm และเพิ่ม E (Evolving) ซึ่งเป็นตัวบ่งชี้สำคัญที่สุดในการติดตาม ส่วนตัวเลข 6% และ 15% ในชีทมาจากการศึกษาดั้งเดิม ปัจจุบันเน้นว่าความเสี่ยงสูงอยู่ที่ตัวผู้ป่วย ไม่ใช่ที่ไฝแต่ละเม็ด',
 mnemonic='<b>"ไฝเยอะ + แม่เป็น = ถ่ายรูปไว้ เทียบทุกรอบ ตัดเฉพาะเม็ดที่เปลี่ยน (E = Evolving)"</b>',
 guide='Bolognia JL, et al. Dermatology 4th ed. (2018) — Benign melanocytic neoplasms; Swetter SM, et al. Guidelines of care for the management of primary cutaneous melanoma. J Am Acad Dermatol 2019',
 variants=[
  'ครอบครัวมี melanoma 3 คน และญาติอีกคนเป็นมะเร็งตับอ่อน → พิจารณาตรวจยีน CDKN2A (familial atypical multiple mole melanoma syndrome)',
  'หญิงที่มีไฝ atypical ตั้งครรภ์แล้วไฝหลายเม็ดเข้มขึ้นเท่า ๆ กันทั้งตัว → การเปลี่ยนสีพร้อมกันจากฮอร์โมนพบได้ แต่เม็ดที่เปลี่ยนต่างจากเม็ดอื่นยังต้อง biopsy',
  'ผลชิ้นเนื้อไฝรายงาน dysplastic nevus with severe atypia และขอบยังมีรอยโรค → ตัดซ้ำให้ได้ขอบปลอดรอยโรค'])

save(Q, 'parts/fill/l22_r13.json')
